// byte from the lesson, written left to right b7..b0
const bits = [0, 1, 0, 1, 0, 0, 1, 1];

// turn each 'on' bit into its place value and add them up
let total = 0;
for (let i = 0; i < bits.length; i++) {
  const place = 1 << (bits.length - 1 - i); // 128, 64, 32, ... , 1
  if (bits[i] === 1) total += place;
}

console.log(total); // the decimal value of 01010011
